#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe http-retry-until-the-server-is-up. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site
printf '%s\n' 'hello from surl' > site/hello.txt
cat > start-late.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Starts curl first and surl two seconds later, as a test that starts both at once may,
# then stops surl once curl is done. Usage: sh start-late.sh <port> [curl options]
port=$1; shift
curl "$@" "http://127.0.0.1:$port/hello.txt" > fetched.txt &
client=$!
sleep 2
surl --directory site "http://127.0.0.1:$port/" > surl.log 2>&1 &
server=$!
wait "$client"
status=$?
kill "$server"
cat fetched.txt
exit $status
EOF
sh start-late.sh 8080 --no-progress-meter --retry 5 --retry-connrefused --retry-delay 1 -w "%{num_retries}\n"
